*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gIsurCd;
scwin.vScrenID = 'ULDSTF30011.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_init = function() {
    scwin.fn_Search();
};
scwin.fn_Search = function() {
    $c.cm.ShowWin(grd_Grid);
    var url = "/DisclosureSchedule.do?method=listSubmitScheduleAdmItems";
    url += "&MKT_ID=" + scwin.gLdMktTp;
    url += "&SUBMIT_SYS_USE_YN=" + $c.stf.getObjectValue(cmb_SUBMIT_SYS_USE_YN);
    url += "&SMS_TRNSM_YN=" + $c.stf.getObjectValue(cmb_SMS_TRNSM_YN);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid.DataID = encodeURI(url);
    dts_Grid.Reset();
};



//팝업에서 보여지는 이미지가 틀려 여기에서 하드코딩으로 넣는다.
scwin.ShowNoData = async function(sval) {
    var tem1 = sval.style.getStyle("width");
    var temLeft = sval.style.left;
    var temTop = sval.style.top;
    var tem2 = sval.style.getStyle("height");
    tem1 = tem1.substring(0, (tem1.length - 2));
    temLeft = temLeft.substring(0, (temLeft.length - 2));
    tem2 = tem2.substring(0, (tem2.length - 2));
    temTop = temTop.substring(0, (temTop.length - 2));
    vXpos = (eval(tem1 / 2) - 100) + Number(temLeft);
    vYpos = (eval(tem2 / 2) - 18) + Number(temTop);
    if ($c.frame.path("NoData") == null) {
        await $c.frame.CreateFrame("NoData", "/common/noData.gfm", "페이지 로딩중...", 143, 148, 200, 35, "sunken", 0, 0, true);
    }
};



//팝업에서 보여지는 이미지가 틀려 여기에서 하드코딩으로 넣는다.
scwin.CloseWin = async function(cnt, sval) {
    if ($c.frame.path("LoadingImg") != null) {
        await $c.frame.CloseFrame();
        if (cnt == 0) $c.cm.ShowNoData(sval);
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {

};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, dts_Grid);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.gform_onload = function() {
    scwin.fn_init();
    $c.cm.PanelToGroupBox(panel_2);
};
